use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GatewayResponse {
    pub transaction_state: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PaymentReceipt {
    pub approved_amount: f64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FiservResponseActions {
    #[serde(rename = "type")]
    pub action_type: String,
    pub url: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FiservResponseInteractions {
    pub actions: FiservResponseActions,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FiservChargesResponse {
    pub gateway_response: GatewayResponse,
    pub payment_receipt: PaymentReceipt,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FiservCheckoutResponse {
    pub gateway_response: GatewayResponse,
    pub payment_receipt: PaymentReceipt,
    pub interactions: FiservResponseInteractions,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum FiservPaymentsResponse {
    Charges(FiservChargesResponse),
    Checkout(FiservCheckoutResponse),
}

fn main() {
    let charge_json = r#"{
        "gatewayResponse": {"transactionState": "CAPTURED"},
        "paymentReceipt": {"approvedAmount": 100.0}
    }"#;

    let checkout_json = r#"{
        "gatewayResponse": {"transactionState": "CREATED"},
        "paymentReceipt": {"approvedAmount": 100.0},
        "interactions": {
            "actions": {
                "type": "REDIRECT",
                "url": "https://example.com"
            }
        }
    }"#;

    println!("=== Charge Response ===");
    match serde_json::from_str::<FiservPaymentsResponse>(charge_json) {
        Ok(v) => println!("Success: {:?}", v),
        Err(e) => println!("Error: {}", e),
    }

    println!("\n=== Checkout Response ===");
    match serde_json::from_str::<FiservPaymentsResponse>(checkout_json) {
        Ok(v) => println!("Success: {:?}", v),
        Err(e) => println!("Error: {}", e),
    }
}
